Reported-by: Shiji Yang <yangshiji66@outlook.com>
Closes: https://lore.kernel.org/all/OS7PR01MB13602B128BA1AD3FA38B6D1FFBC69A@OS7PR01MB13602.jpnprd01.prod.outlook.com/
Fixes: 06f502f57d0d ("leds: trigger: Introduce a NETDEV trigger")
Cc: stable@vger.kernel.org
Signed-off-by: Andrew Lunn <andrew@lunn.ch>
Tested-by: Shiji Yang <yangshiji66@outlook.com>
Link: https://patch.msgid.link/20260222152601.1978655-1-andrew@lunn.ch
Signed-off-by: Paolo Abeni <pabeni@redhat.com>

Here is the root cause:
The PHY LED trigger registration function `phy_led_triggers_register()` was called in `phy_attach_direct()` while holding the RTNL lock. This lock ordering creates an AB-BA deadlock because LED trigger registration acquires `triggers_list_lock`, while another path (LEDS_TRIGGER_NETDEV activation) acquires `triggers_list_lock` first and then tries to acquire RTNL. Moving the call to `phy_probe()` (which does not hold RTNL) resolves the deadlock.

Here is the patch:
  */
 int phy_attach_direct(struct net_device *dev, struct phy_device *phydev,
 		      u32 flags, phy_interface_t interface)
 {
 	struct mii_bus *bus = phydev->mdio.bus;
 	struct device *d = &phydev->mdio.dev;
 	struct module *ndev_owner = NULL;
 	int err;

 	/* For Ethernet device drivers that register their own MDIO bus, we
 	 * will have bus->owner match ndev_mod, so we do not want to increment
 	 * our own module->refcnt here, otherwise we would not be able to
 	 * unload later on.
 	 */
 	if (dev)
 		ndev_owner = dev->dev.parent->driver->owner;
 	if (ndev_owner != bus->owner && !try_module_get(bus->owner)) {
 		phydev_err(phydev, "failed to get the bus module\n");
 		return -EIO;
 	}

 	get_device(d);

 	/* Assume that if there is no driver, that it doesn't
 	 * exist, and we should use the genphy driver.
 	 */
 	if (!d->driver) {
 		if (phydev->is_c45)
 			d->driver = &genphy_c45_driver.mdiodrv.driver;
 		else
 			d->driver = &genphy_driver.mdiodrv.driver;

 		phydev->is_genphy_driven = 1;
 	}

 	if (!try_module_get(d->driver->owner)) {
 		phydev_err(phydev, "failed to get the device driver module\n");
 		err = -EIO;
 		goto error_put_device;
 	}

 	if (phydev->is_genphy_driven) {
 		err = d->driver->probe(d);
 		if (err >= 0)
 			err = device_bind_driver(d);

 		if (err)
 			goto error_module_put;
 	}

 	if (phydev->attached_dev) {
 		dev_err(&dev->dev, "PHY already attached\n");
 		err = -EBUSY;
 		goto error;
 	}

 	phydev->phy_link_change = phy_link_change;
 	if (dev) {
 		phydev->attached_dev = dev;
 		dev->phydev = phydev;

 		if (phydev->sfp_bus_attached)
 			dev->sfp_bus = phydev->sfp_bus;

 		err = phy_link_topo_add_phy(dev, phydev, PHY_UPSTREAM_MAC, dev);
 		if (err)
 			goto error;
 	}

 	/* Some Ethernet drivers try to connect to a PHY device before
 	 * calling register_netdevice() -> netdev_register_kobject() and
 	 * does the dev->dev.kobj initialization. Here we only check for
 	 * success which indicates that the network device kobject is
 	 * ready. Once we do that we still need to keep track of whether
 	 * links were successfully set up or not for phy_detach() to
 	 * remove them accordingly.
 	 */
 	phydev->sysfs_links = false;

 	phy_sysfs_create_links(phydev);

 	if (!phydev->attached_dev) {
 		err = sysfs_create_file(&phydev->mdio.dev.kobj,
 					&dev_attr_phy_standalone.attr);
 		if (err)
 			phydev_err(phydev, "error creating 'phy_standalone' sysfs entry\n");
 	}

 	phydev->dev_flags |= flags;

 	phydev->interface = interface;

 	phydev->state = PHY_READY;

 	phydev->interrupts = PHY_INTERRUPT_DISABLED;

 	/* PHYs can request to use poll mode even though they have an
 	 * associated interrupt line. This could be the case if they
 	 * detect a broken interrupt handling.
 	 */
 	if (phydev->dev_flags & PHY_F_NO_IRQ)
 		phydev->irq = PHY_POLL;

 	if (!phy_drv_supports_irq(phydev->drv) && phy_interrupt_is_valid(phydev))
 		phydev->irq = PHY_POLL;

 	/* Port is set to PORT_TP by default and the actual PHY driver will set
 	 * it to different value depending on the PHY configuration. If we have
 	 * the generic PHY driver we can't figure it out, thus set the old
 	 * legacy PORT_MII value.
 	 */
 	if (phydev->is_genphy_driven)
 		phydev->port = PORT_MII;

 	/* Initial carrier state is off as the phy is about to be
 	 * (re)initialized.
 	 */
 	if (dev)
 		netif_carrier_off(phydev->attached_dev);

 	/* Do initial configuration here, now that
 	 * we have certain key parameters
 	 * (dev_flags and interface)
 	 */
 	err = phy_init_hw(phydev);
 	if (err)
 		goto error;

 	phy_resume(phydev);
-	if (!phydev->is_on_sfp_module)
-		phy_led_triggers_register(phydev);

 	/**
 	 * If the external phy used by current mac interface is managed by
 	 * another mac interface, so we should create a device link between
 	 * phy dev and mac dev.
 	 */
 	if (dev && phydev->mdio.bus->parent && dev->dev.parent != phydev->mdio.bus->parent)
 		phydev->devlink = device_link_add(dev->dev.parent, &phydev->mdio.dev,
 						  DL_FLAG_PM_RUNTIME | DL_FLAG_STATELESS);

 	return err;

 error:
 	/* phy_detach() does all of the cleanup below */
 	phy_detach(phydev);
 	return err;

 error_module_put:
 	module_put(d->driver->owner);
 	phydev->is_genphy_driven = 0;
 	d->driver = NULL;
 error_put_device:
 	put_device(d);
 	if (ndev_owner != bus->owner)
 		module_put(bus->owner);
 	return err;
 }
 EXPORT_SYMBOL(phy_attach_direct);
  */
 void phy_detach(struct phy_device *phydev)
 {
 	struct net_device *dev = phydev->attached_dev;
 	struct module *ndev_owner = NULL;
 	struct mii_bus *bus;

 	if (phydev->devlink) {
 		device_link_del(phydev->devlink);
 		phydev->devlink = NULL;
 	}

 	if (phydev->sysfs_links) {
 		if (dev)
 			sysfs_remove_link(&dev->dev.kobj, "phydev");
 		sysfs_remove_link(&phydev->mdio.dev.kobj, "attached_dev");
 	}

 	if (!phydev->attached_dev)
 		sysfs_remove_file(&phydev->mdio.dev.kobj,
 				  &dev_attr_phy_standalone.attr);

 	phy_suspend(phydev);
 	if (dev) {
 		struct hwtstamp_provider *hwprov;

 		hwprov = rtnl_dereference(dev->hwprov);
 		/* Disable timestamp if it is the one selected */
 		if (hwprov && hwprov->phydev == phydev) {
 			rcu_assign_pointer(dev->hwprov, NULL);
 			kfree_rcu(hwprov, rcu_head);
 		}

 		phydev->attached_dev->phydev = NULL;
 		phydev->attached_dev = NULL;
 		phy_link_topo_del_phy(dev, phydev);
 	}

 	phydev->phy_link_change = NULL;
 	phydev->phylink = NULL;

-	if (!phydev->is_on_sfp_module)
-		phy_led_triggers_unregister(phydev);
-
 	if (phydev->mdio.dev.driver)
 		module_put(phydev->mdio.dev.driver->owner);

 	/* If the device had no specific driver before (i.e. - it
 	 * was using the generic driver), we unbind the device
 	 * from the generic driver so that there's a chance a
 	 * real driver could be loaded
 	 */
 	if (phydev->is_genphy_driven) {
 		device_release_driver(&phydev->mdio.dev);
 		phydev->is_genphy_driven = 0;
 	}

 	/* Assert the reset signal */
 	phy_device_reset(phydev, 1);

 	/*
 	 * The phydev might go away on the put_device() below, so avoid
 	 * a use-after-free bug by reading the underlying bus first.
 	 */
 	bus = phydev->mdio.bus;

 	put_device(&phydev->mdio.dev);
 	if (dev)
 		ndev_owner = dev->dev.parent->driver->owner;
 	if (ndev_owner != bus->owner)
 		module_put(bus->owner);
 }
 EXPORT_SYMBOL(phy_detach);
  */
 static int phy_probe(struct device *dev)
 {
 	struct phy_device *phydev = to_phy_device(dev);
 	struct device_driver *drv = phydev->mdio.dev.driver;
 	struct phy_driver *phydrv = to_phy_driver(drv);
 	int err = 0;

 	phydev->drv = phydrv;

 	/* Disable the interrupt if the PHY doesn't support it
 	 * but the interrupt is still a valid one
 	 */
 	if (!phy_drv_supports_irq(phydrv) && phy_interrupt_is_valid(phydev))
 		phydev->irq = PHY_POLL;

 	if (phydrv->flags & PHY_IS_INTERNAL)
 		phydev->is_internal = true;

 	/* Deassert the reset signal */
 	phy_device_reset(phydev, 0);

 	if (phydev->drv->probe) {
 		err = phydev->drv->probe(phydev);
 		if (err)
 			goto out;
 	}

 	phy_disable_interrupts(phydev);

 	/* Start out supporting everything. Eventually,
 	 * a controller will attach, and may modify one
 	 * or both of these values
 	 */
 	if (phydrv->features) {
 		linkmode_copy(phydev->supported, phydrv->features);
 		genphy_c45_read_eee_abilities(phydev);
 	}
 	else if (phydrv->get_features)
 		err = phydrv->get_features(phydev);
 	else if (phydev->is_c45)
 		err = genphy_c45_pma_read_abilities(phydev);
 	else
 		err = genphy_read_abilities(phydev);

 	if (err)
 		goto out;

 	if (!linkmode_test_bit(ETHTOOL_LINK_MODE_Autoneg_BIT,
 			       phydev->supported))
 		phydev->autoneg = 0;

 	if (linkmode_test_bit(ETHTOOL_LINK_MODE_1000baseT_Half_BIT,
 			      phydev->supported))
 		phydev->is_gigabit_capable = 1;
 	if (linkmode_test_bit(ETHTOOL_LINK_MODE_1000baseT_Full_BIT,
 			      phydev->supported))
 		phydev->is_gigabit_capable = 1;

 	of_set_phy_supported(phydev);

 	err = phy_setup_ports(phydev);
 	if (err)
 		goto out;

 	phy_advertise_supported(phydev);

 	/* Get PHY default EEE advertising modes and handle them as potentially
 	 * safe initial configuration.
 	 */
 	err = genphy_c45_read_eee_adv(phydev, phydev->advertising_eee);
 	if (err)
 		goto out;

 	/* Get the EEE modes we want to prohibit. */
 	of_set_phy_eee_broken(phydev);

 	/* Some PHYs may advertise, by default, not support EEE modes. So,
 	 * we need to clean them. In addition remove all disabled EEE modes.
 	 */
 	linkmode_and(phydev->advertising_eee, phydev->supported_eee,
 		     phydev->advertising_eee);
 	linkmode_andnot(phydev->advertising_eee, phydev->advertising_eee,
 			phydev->eee_disabled_modes);

 	/* There is no "enabled" flag. If PHY is advertising, assume it is
 	 * kind of enabled.
 	 */
 	phydev->eee_cfg.eee_enabled = !linkmode_empty(phydev->advertising_eee);

 	/* Get master/slave strap overrides */
 	of_set_phy_timing_role(phydev);

 	/* The Pause Frame bits indicate that the PHY can support passing
 	 * pause frames. During autonegotiation, the PHYs will determine if
 	 * they should allow pause frames to pass.  The MAC driver should then
 	 * use that result to determine whether to enable flow control via
 	 * pause frames.
 	 *
 	 * Normally, PHY drivers should not set the Pause bits, and instead
 	 * allow phylib to do that.  However, there may be some situations
 	 * (e.g. hardware erratum) where the driver wants to set only one
 	 * of these bits.
 	 */
 	if (!test_bit(ETHTOOL_LINK_MODE_Pause_BIT, phydev->supported) &&
 	    !test_bit(ETHTOOL_LINK_MODE_Asym_Pause_BIT, phydev->supported)) {
 		linkmode_set_bit(ETHTOOL_LINK_MODE_Pause_BIT,
 				 phydev->supported);
 		linkmode_set_bit(ETHTOOL_LINK_MODE_Asym_Pause_BIT,
 				 phydev->supported);
 	}

 	/* Set the state to READY by default */
 	phydev->state = PHY_READY;

+	/* Register the PHY LED triggers */
+	if (!phydev->is_on_sfp_module)
+		phy_led_triggers_register(phydev);
+
 	/* Get the LEDs from the device tree, and instantiate standard
 	 * LEDs for them.
 	 */
-	if (IS_ENABLED(CONFIG_PHYLIB_LEDS) && !phy_driver_is_genphy(phydev))
+	if (IS_ENABLED(CONFIG_PHYLIB_LEDS) && !phy_driver_is_genphy(phydev)) {
 		err = of_phy_leds(phydev);
+		if (err)
+			goto out;
+	}
+
+	return 0;

 out:
+	if (!phydev->is_on_sfp_module)
+		phy_led_triggers_unregister(phydev);
+
 	/* Re-assert the reset signal on error */
-	if (err)
-		phy_device_reset(phydev, 1);
+	phy_device_reset(phydev, 1);

 	return err;
 }

 static int phy_remove(struct device *dev)
 {
 	struct phy_device *phydev = to_phy_device(dev);

 	cancel_delayed_work_sync(&phydev->state_queue);

 	if (IS_ENABLED(CONFIG_PHYLIB_LEDS) && !phy_driver_is_genphy(phydev))
 		phy_leds_unregister(phydev);

+	if (!phydev->is_on_sfp_module)
+		phy_led_triggers_unregister(phydev);
+
 	phydev->state = PHY_DOWN;

 	phy_cleanup_ports(phydev);

 	sfp_bus_del_upstream(phydev->sfp_bus);
 	phydev->sfp_bus = NULL;

 	if (phydev->drv && phydev->drv->remove)
 		phydev->drv->remove(phydev);

 	/* Assert the reset signal */
 	phy_device_reset(phydev, 1);

 	phydev->drv = NULL;

 	return 0;
 }



Provide a response strictly in the following format:

The code statements that lead to the bug are:
<text>
<text>
...
<text>
